from collections import defaultdict
from typing import Dict, List, Tuple

def get_stats(vocab):
    pairs = defaultdict(int)
    for word, freq in vocab.items():
        symbols = word.split()
        for i in range(len(symbols) - 1):
            pairs[(symbols[i], symbols[i + 1])] += freq
    return pairs

def merge_vocab(pair, v_in):
    v_out = {}
    bigram = ' '.join(pair)
    replacement = ''.join(pair)
    for word in v_in:
        w_out = ' ' + word + ' '
        w_out = w_out.replace(' ' + bigram + ' ', ' ' + replacement + ' ')
        v_out[w_out.strip()] = v_in[word]
    return v_out

def train_bpe_step(corpus: Dict[str, int], num_merges: int = 3) -> List[Tuple[str, str]]:
    vocab = corpus.copy()
    merges = []
    for _ in range(num_merges):
        pairs = get_stats(vocab)
        if not pairs:
            break
        best_pair = max(pairs, key=pairs.get)
        merges.append(best_pair)
        vocab = merge_vocab(best_pair, vocab)
    return merges

corpus = {'l o w </w>': 5, 'l o w e r </w>': 2, 'n e w e s t </w>': 6, 'w i d e s t </w>': 3}
rules = train_bpe_step(corpus, 3)
print(len(rules))

